import pandas as pd


def _differs(a, b):
    """NULL-aware inequality: NULL vs NULL -> not differs; NULL vs non-NULL -> differs;
    non-NULL vs non-NULL -> standard inequality."""
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _pick_latest(group: pd.DataFrame) -> pd.Series:
    max_date = group['update_date'].max()
    candidates = group[group['update_date'] == max_date]
    if len(candidates) == 1:
        return candidates.iloc[0]
    # Tie-break: greater (email, tier) lexicographic pair wins.
    candidates = candidates.sort_values(by=['email', 'tier'], ascending=[False, False])
    return candidates.iloc[0]


